// v0.10.0 E2 — build-time release-notes module generator.
//
// Extracts the CURRENT package.json version's section from CHANGELOG.md and
// writes src/lib/release-notes/notes.generated.ts so the in-app What's-new
// panel can render it as a plain imported module. Importing the text (instead
// of fs.readFile-ing CHANGELOG.md at request time) is what makes the feature
// survive `output: 'standalone'`: the file tracer only copies modules the
// build graph imports, and CHANGELOG.md is not in the production image.
//
// The generated file IS committed (typecheck needs it). Drift between
// CHANGELOG.md / package.json and the committed module is caught by
// tests/scripts/generate-release-notes.test.ts, and `pnpm build` re-runs this
// script (`pnpm notes:gen`) before `next build` regardless.
//
// Parse/render logic is exported so the drift-guard test can import it; the
// CLI body is guarded by an import.meta.url check (types in the sibling
// generate-release-notes.d.mts).
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

/**
 * Extract the CHANGELOG section for `version`, INCLUDING its `## ` heading
 * line. Heading format (Keep a Changelog): `## [0.9.19] - 2026-06-10`; bare
 * `## 0.9.19` headings are tolerated. The match is EXACT — a running version
 * newer than every tagged section (local dev ahead of tags) returns null so
 * the panel shows its fallback instead of a stale older section.
 *
 * @param {string} changelog
 * @param {string} version
 * @returns {string | null}
 */
export function extractSection(changelog, version) {
  const lines = changelog.split(/\r?\n/);
  const headingVersion = (line) => {
    const m = /^##\s+(?:\[([^\]]+)\]|(\S+))(?:\s+.*)?$/.exec(line);
    if (!m) return null;
    return m[1] ?? m[2] ?? null;
  };
  const start = lines.findIndex((line) => headingVersion(line) === version);
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i++) {
    if (/^##\s/.test(lines[i] ?? '')) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n').trim();
}

/**
 * Render the TypeScript module source for a `{ version, markdown }` payload.
 *
 * @param {string} version
 * @param {string | null} markdown
 * @returns {string}
 */
export function renderModule(version, markdown) {
  return [
    '// AUTO-GENERATED by scripts/generate-release-notes.mjs (`pnpm notes:gen`) — do not edit.',
    '// Drift guard: tests/scripts/generate-release-notes.test.ts. Excluded from Biome.',
    '',
    'export type ReleaseNotes = {',
    '  /** package.json version the notes were extracted for. */',
    '  version: string;',
    '  /** Matching CHANGELOG.md section (incl. heading), or null when absent. */',
    '  markdown: string | null;',
    '};',
    '',
    'export const releaseNotes: ReleaseNotes = {',
    `  version: ${JSON.stringify(version)},`,
    `  markdown: ${markdown === null ? 'null' : JSON.stringify(markdown)},`,
    '};',
    '',
  ].join('\n');
}

/**
 * Read package.json + CHANGELOG.md under `repoRoot` and produce the module.
 *
 * @param {string} repoRoot
 * @returns {{ version: string, markdown: string | null, source: string }}
 */
export function generate(repoRoot) {
  const pkg = JSON.parse(readFileSync(join(repoRoot, 'package.json'), 'utf8'));
  const changelog = readFileSync(join(repoRoot, 'CHANGELOG.md'), 'utf8');
  const markdown = extractSection(changelog, pkg.version);
  return { version: pkg.version, markdown, source: renderModule(pkg.version, markdown) };
}

const isMain =
  process.argv[1] !== undefined && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
  const outFile = join(repoRoot, 'src', 'lib', 'release-notes', 'notes.generated.ts');
  const { version, markdown, source } = generate(repoRoot);
  mkdirSync(dirname(outFile), { recursive: true });
  writeFileSync(outFile, source);
  console.info(
    `release-notes: v${version} — ${
      markdown === null
        ? 'no CHANGELOG section (panel will show its fallback)'
        : 'section extracted'
    } → ${outFile}`,
  );
}
